import 'package:flutter/material.dart';import 'package:url_launcher/url_launcher.dart';import '../models/room.dart';import '../services/app_services.dart';import 'chat.dart';
class RoomDetail extends StatelessWidget{final Room room;const RoomDetail({super.key,required this.room});Future<void> call()async{final d=await db.collection('users').doc(room.ownerId).get();final p=d.data()?['phone'];if(p!=null)await launchUrl(Uri.parse('tel:$p'));}
Widget build(BuildContext c)=>Scaffold(appBar:AppBar(actions:[StreamBuilder<bool>(stream:FavoriteService().isFavorite(room.id),builder:(c,s)=>IconButton(onPressed:()=>FavoriteService().toggle(room),icon:Icon(s.data==true?Icons.favorite:Icons.favorite_border))) ]),body:ListView(children:[if(room.photos.isNotEmpty)SizedBox(height:270,child:PageView(children:room.photos.map((p)=>Image.network(p,fit:BoxFit.cover)).toList())),Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(room.title,style:const TextStyle(fontSize:25,fontWeight:FontWeight.bold)),Text('${room.area}, ${room.city}'),const SizedBox(height:12),Text('Rs. ${room.rent}/month',style:const TextStyle(fontSize:22,fontWeight:FontWeight.bold)),Text('Deposit: Rs. ${room.deposit}'),const SizedBox(height:16),Wrap(spacing:8,children:[if(room.furnished)const Chip(label:Text('Furnished')),if(room.bathroom)const Chip(label:Text('Private bath')),if(room.kitchen)const Chip(label:Text('Kitchen')),if(room.parking)const Chip(label:Text('Parking')),if(room.wifi)const Chip(label:Text('Wi‑Fi'))]),const SizedBox(height:12),Text(room.description),const SizedBox(height:24),Row(children:[Expanded(child:FilledButton.icon(onPressed:call,icon:const Icon(Icons.call),label:const Text('Call'))),const SizedBox(width:10),Expanded(child:OutlinedButton.icon(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>ChatPage(conversationId:ChatService().cid(auth.currentUser!.uid,room.ownerId,room.id),roomId:room.id,receiverId:room.ownerId)),icon:const Icon(Icons.chat),label:const Text('Message'))))])]))]));}
}
